function model(p) {
  // Illustrative synthetic data: monthly new hires for three regions, Jan 2024 to Dec 2025.
  // A seeded generator (mulberry32) keeps the numbers identical on every run. Five warm-up months
  // (Aug to Dec 2023) are generated but not shown, so every displayed month has a full smoothing window.
  let seed = 20240101;
  const rnd = () => { seed = seed + 0x6D2B79F5 | 0; let t = Math.imul(seed ^ seed >>> 15, 1 | seed); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; };
  const MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  const SEASON = [1.06, 1.0, 1.1, 1.04, 0.98, 0.95, 0.9, 0.93, 1.08, 1.05, 0.97, 0.8];
  const WARM = 5, N = 24;
  const DEFS = [
    { name: 'North America', short: 'N. America', base: 118, growth: 0.004 },
    { name: 'EMEA', short: 'EMEA', base: 84, growth: 0.012 },
    { name: 'APAC', short: 'APAC', base: 46, growth: 0.028 }
  ];
  const months = [];
  for (let i = 0; i < N; i++) months.push({ label: MON[i % 12] + ' ' + (2024 + Math.floor(i / 12)), short: MON[i % 12] });
  const w = [1, 3, 6][Math.max(0, Math.min(2, Math.round(p.smoothing)))];
  const view = Math.round(p.show) === 1 ? 'change' : 'monthly';
  const regions = DEFS.map((d, r) => {
    const all = [];
    for (let k = 0; k < N + WARM; k++) {
      const m = (k + 12 - WARM) % 12; // k = 0 is Aug 2023
      all.push(Math.round(d.base * Math.pow(1 + d.growth, k - WARM) * SEASON[m] * (1 + (rnd() - 0.5) * 0.12)));
    }
    const raw = all.slice(WARM);
    const smooth = raw.map((_, i) => { const win = all.slice(i + WARM - w + 1, i + WARM + 1); return win.reduce((a, b) => a + b, 0) / w; });
    const change = smooth.map((v, i) => i >= 12 ? (v / smooth[i - 12] - 1) * 100 : null);
    const last6 = raw.slice(18, 24).reduce((a, b) => a + b, 0), prev6 = raw.slice(6, 12).reduce((a, b) => a + b, 0);
    return { name: d.name, short: d.short, index: r, raw, smooth, change, all, total: raw.reduce((a, b) => a + b, 0),
      last6, prev6, growth: (last6 / prev6 - 1) * 100 };
  });
  const fastest = regions.reduce((b, r) => r.growth > b.growth ? r : b, regions[0]).index;
  const shown = view === 'monthly' ? months.map((_, i) => i) : months.map((_, i) => i).filter(i => i >= 12);
  const revealEnd = 10, annotateAt = 10.8, duration = 12;
  const revealAt = shown.map((_, k) => +(0.4 + k * (revealEnd - 0.4) / (shown.length - 1)).toFixed(3));
  const at = i => revealAt[shown.indexOf(i)];
  const markers = view === 'monthly' ? [0.4, at(11), at(18), revealEnd, annotateAt] : [0.4, at(18), revealEnd, annotateAt];
  const f = regions[fastest], others = regions.filter(r => r.index !== fastest).sort((a, b) => b.growth - a.growth);
  const pct = v => (v >= 0 ? '+' : '') + Math.round(v) + '%';
  const summary = f.short + ' is growing fastest: ' + pct(f.growth) + ' hires in Jul–Dec 2025 vs Jul–Dec 2024 (' +
    others.map(r => r.short + ' ' + pct(r.growth)).join(', ') + ').';
  return { months, regions, fastest, window: w, view, shown, revealAt, annotateAt, duration, markers, summary,
    windowLabel: w === 1 ? 'no smoothing' : w + '-month average' };
}

