function check(p) {
  const m = model(p), R = m.regions, w = m.window;
  // 1. The highlighted region is the one with the highest computed growth (last 6 months vs same months a year earlier).
  const g = R.map(r => { const a = r.raw.slice(18, 24).reduce((s, v) => s + v, 0), b = r.raw.slice(6, 12).reduce((s, v) => s + v, 0); return a / b - 1; });
  const best = g.indexOf(Math.max(...g));
  const highlightOk = m.fastest === best && R.every((r, i) => Math.abs(r.growth / 100 - g[i]) < 1e-9);
  // 2. Each smoothed value is the mean of its window, so it lies between that window's lowest and highest month.
  const smoothOk = R.every(r => r.smooth.every((v, i) => {
    const win = r.all.slice(i + 5 - w + 1, i + 6), mean = win.reduce((s, x) => s + x, 0) / w;
    return win.length === w && Math.abs(v - mean) < 1e-9 && v >= Math.min(...win) - 1e-9 && v <= Math.max(...win) + 1e-9;
  }));
  // 3. Smoothing does not change which region hires the most in total.
  const order = a => R.map((r, i) => [a(r), i]).sort((x, y) => y[0] - x[0]).map(x => x[1]).join();
  const orderOk = order(r => r.raw.reduce((s, v) => s + v, 0)) === order(r => r.smooth.reduce((s, v) => s + v, 0));
  // 4. Change vs same month last year is computed from the displayed (smoothed) series.
  const changeOk = R.every(r => r.change.every((v, i) => i < 12 ? v === null : Math.abs(v - (r.smooth[i] / r.smooth[i - 12] - 1) * 100) < 1e-9));
  const f = R[m.fastest];
  return { pass: highlightOk && smoothOk && orderOk && changeOk,
    detail: f.short + ' has the highest growth (' + f.last6 + ' vs ' + f.prev6 + ' hires, ' + (g[m.fastest] * 100).toFixed(1) + '%) and is the one highlighted; with ' + (w === 1 ? 'raw months' : 'a ' + m.windowLabel) +
      ' every smoothed month equals its window mean and the total-hires order (' + order(r => r.total).split(',').map(i => R[i].short).join(' > ') + ') is unchanged.' };
}
